\textbf{P1.} \emph{Let $A_1 \subseteq A_2 \subseteq A_3 \dots$ be an increasing sequence of measurable sets. Show that $m(\cup_{j=1}^\infty A_j) = \lim_{j \to \infty} m(A_j)$.}

\medskip
Define $B_1 = A_1$, and for $j \geq 2$ set $B_j = A_j \setminus A_{j-1}$. Then the $B_j$ are disjoint and measurable, and $\bigcup_{j=1}^\infty A_j = \bigsqcup_{j=1}^\infty B_j$ (a disjoint union). By countable additivity,
\[m\!\left(\bigcup_{j=1}^\infty A_j\right)=m\!\left(\bigsqcup_{j=1}^\infty B_j\right)=\sum_{j=1}^\infty m(B_j).\]
Since $m(A_j) = \sum_{k=1}^j m(B_k)$, taking the limit gives $\lim_{j\to\infty} m(A_j) = \sum_{j=1}^\infty m(B_j) = m(\bigcup A_j)$.

\medskip

\textbf{P2.} \emph{Let $A_1 \supseteq A_2 \supseteq A_3 \dots$ be a decreasing sequence of measurable sets with $m(A_1) < +\infty$. Show that $m(\cap_{j=1}^\infty A_j) = \lim_{j \to \infty} m(A_j)$.}

\medskip
Since $m(A_1) < \infty$, the sets $C_j = A_1 \setminus A_j$ form an increasing sequence of measurable sets. By P1,
\[m\!\left(\bigcup_{j=1}^\infty C_j\right)=\lim_{j\to\infty} m(C_j).\]
But $\bigcup_j C_j = A_1 \setminus \bigcap_{j=1}^\infty A_j$ and $m(C_j) = m(A_1) - m(A_j)$. Hence
\[m(A_1)-m\!\left(\bigcap_{j=1}^\infty A_j\right)=\lim_{j\to\infty}\bigl(m(A_1)-m(A_j)\bigr),\]
so $m(\bigcap_j A_j) = \lim_{j\to\infty} m(A_j)$.

\medskip

\textbf{P3.} \emph{Let $\Omega$ be measurable and $f: \Omega \to [0,\infty]$ be non-negative measurable with $\int_\Omega f$ finite. Show that $f$ is finite almost everywhere (i.e., $\{x : f(x)=+\infty\}$ has measure zero).}

\medskip
Define $E_k = \{x \in \Omega: f(x) > k\}$ for each $k \in \N$. Then $E_k$ is measurable and $E_k \downarrow \bigcap_{k=1}^\infty E_k = \{f = \infty\}$. Now $k \cdot \chi_{E_k} \leq f \cdot \chi_{E_k} \leq f$, so integrating gives $k \cdot m(E_k) \leq \int_{E_k} f \leq \int_\Omega f < \infty$. Hence $m(E_k) \leq \frac{1}{k} \int_\Omega f \to 0$ as $k \to \infty$. Since $\{f = \infty\} \subseteq E_k$ for every $k$, we have $m(\{f=\infty\}) \leq m(E_k) \to 0$, so $m(\{f=\infty\}) = 0$.

\medskip

\textbf{P4.} \emph{(Borel--Cantelli Lemma) Let $\Omega_1, \Omega_2, \dots$ be measurable with $\sum_{n=1}^\infty m(\Omega_n) < \infty$. Show that $\{x : x \in \Omega_n \text{ for infinitely many } n\}$ has measure zero.}

\medskip
Let
\[E = \bigcap_{N=1}^\infty \bigcup_{n=N}^\infty \Omega_n.\]
For each $N$, by countable sub-additivity,
\[m\!\left(\bigcup_{n=N}^\infty \Omega_n\right) \leq \sum_{n=N}^\infty m(\Omega_n).\]
Since $\sum_{n=1}^\infty m(\Omega_n) < \infty$, the tail sum $\sum_{n=N}^\infty m(\Omega_n) \to 0$ as $N \to \infty$. The sets $\bigcup_{n=N}^\infty \Omega_n$ decrease with $N$, so by continuity from above (which applies since $m(\bigcup_{n=1}^\infty \Omega_n) \leq \sum m(\Omega_n) < \infty$),
\[m(E) = \lim_{N\to\infty} m\!\left(\bigcup_{n=N}^\infty \Omega_n\right) = 0.\]

\medskip

\textbf{P5.} \emph{Let $p > 2$ and $c > 0$. Show that the set $\{x \in [0,1] : |x - a/q| \leq c/q^p \text{ for infinitely many } a, q \in \N\}$ has measure zero.}

\medskip
For each $q \in \N$ and each $a \in \{0,1,\dots,q\}$, define
\[\Omega_{a,q} = \left\{x \in [0,1] : \left|x - \frac{a}{q}\right| \le \frac{c}{q^p}\right\}.\]
This is an interval of length $2c/q^p$, so $m(\Omega_{a,q}) = 2c/q^p$. There are $q+1$ such intervals for each $q$. The set
\[E = \left\{x \in [0,1] : |x-a/q| \le c/q^p \text{ for infinitely many } a,q\right\} = \bigcap_{N=1}^\infty \bigcup_{q=N}^\infty \bigcup_{a=0}^q \Omega_{a,q}.\]
Summing the measures: for each $q$,
\[\sum_{a=0}^q m(\Omega_{a,q}) = \frac{2c(q+1)}{q^p}.\]
Summing over all $q \geq 1$:
\[\sum_{q=1}^\infty \frac{2c(q+1)}{q^p} = 2c \sum_{q=1}^\infty \left(\frac{1}{q^{p-1}} + \frac{1}{q^p}\right) < \infty\]
since $p > 2$ implies both $p-1 > 1$ and $p > 1$. By the Borel--Cantelli lemma (P4), $m(E) = 0$.

\medskip

\textbf{P6.} \emph{Let $\Omega$ be measurable and $f: \Omega \to \R^* = \R \cup \{\pm\infty\}$ be absolutely integrable. Prove $|\int_\Omega f| \leq \int_\Omega |f|$.}

\medskip
Since $f$ is absolutely integrable, $\int_\Omega |f| < \infty$. Write $f = f^+ - f^-$ with $f^+ = \max(f,0) \geq 0$, $f^- = -\min(f,0) \geq 0$, and $|f| = f^+ + f^-$. All three functions are non-negative and have finite integrals. Then
\[|\int_\Omega f| = \left|\int_\Omega f^+ - \int_\Omega f^-\right| \le \int_\Omega f^+ + \int_\Omega f^- = \int_\Omega (f^+ + f^-) = \int_\Omega |f|.\]

\medskip

\textbf{P7.} \emph{Let $f: \Omega \to \R$ be absolutely integrable and let $c \in \R$. Show that $cf$ is absolutely integrable and $\int_\Omega cf = c \int_\Omega f$.}

\medskip
If $c = 0$, the result is trivial. If $c \neq 0$, then $|cf| = |c| \cdot |f|$, so $\int_\Omega |cf| = |c| \int_\Omega |f| < \infty$, hence $cf \in L^1$. For the integral, if $c > 0$ then $(cf)^+ = c f^+$ and $(cf)^- = c f^-$, so $\int cf = c\int f^+ - c\int f^- = c\int f$. If $c < 0$, then $(cf)^+ = |c| f^-$ and $(cf)^- = |c| f^+$, so $\int cf = |c|\int f^- - |c|\int f^+ = c(\int f^+ - \int f^-)= c\int f$.

\medskip

\textbf{P8.} \emph{Let $f, g: \Omega \to \R$ be absolutely integrable. Show that $f+g$ is absolutely integrable and $\int_\Omega (f+g) = \int_\Omega f + \int_\Omega g$.}

\medskip
Since $|f+g| \leq |f| + |g|$ pointwise, $\int_\Omega |f+g| \leq \int_\Omega |f| + \int_\Omega |g| < \infty$, so $f+g \in L^1$. To show linearity, one can verify that $(f+g)^+ - (f+g)^- = f^+ - f^- + g^+ - g^-$. Integrating all terms (which are non-negative and have finite integrals) gives
\[\int (f+g)^+ + \int f^- + \int g^- = \int (f+g)^- + \int f^+ + \int g^+,\]
which rearranges to $\int (f+g) = \int f + \int g$.

\medskip

\textbf{P9.} \emph{Let $f, g: \Omega \to \R$ be absolutely integrable and $f(x) \leq g(x)$ for all $x$. Show $\int_\Omega f \leq \int_\Omega g$.}

\medskip
Since $g - f \geq 0$ pointwise and $g - f$ is measurable, by non-negativity of the Lebesgue integral (Proposition 8.1.10 in Tao), $\int_\Omega (g-f) \geq 0$. By linearity from P8, $\int g - \int f = \int (g-f) \geq 0$, so $\int f \leq \int g$.

\medskip

\textbf{P10.} \emph{Let $f, g: \Omega \to \R$ be absolutely integrable and $f(x) = g(x)$ for almost every $x$. Show $\int_\Omega f = \int_\Omega g$.}

\medskip
Let $E = \{x : f(x) \neq g(x)\}$. Since $m(E) = 0$,
\[\int_\Omega f = \int_{\Omega \setminus E} f + \int_E f = \int_{\Omega \setminus E} g + \int_E g = \int_\Omega g,\]
because $m(E) = 0$ implies $\int_E f = \int_E g = 0$.

